        static float Sample(float[] a, float t)
        {
            float f = t * Fps;
            if (f <= 0f) return a[0];
            int i = (int)f;
            if (i >= a.Length - 1) return a[a.Length - 1];
            return a[i] + (a[i + 1] - a[i]) * (f - i);
        }

        public static float Angle(float t) => Sample(StarAngle, t);
        public static float Scale(float t) => Sample(StarScale, t);
        public static float Ray(float t) => Sample(StarRay, t);
        public static float Sharp(float t) => Sample(StarSharp, t);

        public static UnityEngine.Vector2 PathAt(float u)
        {
            float f = UnityEngine.Mathf.Clamp01(u) * (PathX.Length - 1);
            int i = UnityEngine.Mathf.Min((int)f, PathX.Length - 2);
            float k = f - i;
            return new UnityEngine.Vector2(PathX[i] + (PathX[i + 1] - PathX[i]) * k, PathY[i] + (PathY[i + 1] - PathY[i]) * k);
        }
    }
